import sys
import shiboken2
import maya.OpenMayaUI as omui
import pymel.core as pm
from PySide2 import QtWidgets, QtCore, QtGui


def get_maya_main_window():
    main_window_ptr = omui.MQtUtil.mainWindow()
    if sys.version_info.major >= 3:
        return shiboken2.wrapInstance(int(main_window_ptr), QtWidgets.QWidget)
    else:
        return shiboken2.wrapInstance(long(main_window_ptr), QtWidgets.QWidget)


def find_maya_widget(objectName=None):
    maya_main_widget = get_maya_main_window()
    types = [QtWidgets.QWidget, QtWidgets.QAction]
    for t in types:
        widget_obj = maya_main_widget.findChildren(t)
        for w in widget_obj:
            if w.objectName() == objectName:
                return w


def setFont(objectName=None):
    w = find_maya_widget(objectName)
    w.setFont(QtGui.QFont(u'微软雅黑'))

def optimize_abc_node():
    alembic_nodes = pm.ls(type='AlembicNode')
    for node in alembic_nodes:
        outputs = node.outputs(plugs=True)
        if node.isReferenced():
            continue
        if outputs == []:
            pm.delete(node)
